import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen0Test {





    @Test
    public void testContainsNone_BasicBMP() {
        // No matches
        assertTrue(StringUtils.containsNone("def", new char[]{'a', 'b', 'c'}));
        // Match found (BMP character)
        assertFalse(StringUtils.containsNone("abc", new char[]{'b', 'z'}));
        // Multiple matches
        assertFalse(StringUtils.containsNone("apple", new char[]{'a', 'p'}));
    }






}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen0Test {







    @Test
    public void testContainsNone_HighSurrogateMatch() {
        // Unicode Emoji: U+1F600 (Grinning Face)
        // High Surrogate: \uD83D, Low Surrogate: \uDE00
        String emoji = "\uD83D\uDE00";
        char[] searchChars = {'\uD83D', '\uDE00'};

        // Full surrogate pair match
        assertFalse(StringUtils.containsNone(emoji, searchChars));

        // Partial match: High surrogate only in searchChars at the end
        // The logic says: if (j == searchLast) return false; 
        // Wait, if j is the last index and it is a high surrogate, it returns false (meaning it FOUND a match/invalid char)
        char[] searchOnlyHigh = {'\uD83D'};
        assertFalse(StringUtils.containsNone(emoji, searchOnlyHigh));

        // Partial match: High surrogate in searchChars but not followed by correct low surrogate in cs
        char[] searchWrongLow = {'\uD83D', '\uDE01'};
        assertTrue(StringUtils.containsNone(emoji, searchWrongLow));
    }




}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen0Test {









    @Test
    public void testContainsNone_SurrogateEdgeCases() {
        // Test logic: if (i < csLast && searchChars[j + 1] == cs.charAt(i + 1))
        // This handles the surrogate pair verification.

        String emoji = "\uD83D\uDE00"; // Grinning Face

        // Case: searchChars contains high surrogate but it's the last element in searchChars
        // The code: if (j == searchLast) return false;
        char[] searchLastIsHigh = {'a', 'b', '\uD83D'};
        assertFalse(StringUtils.containsNone(emoji, searchLastIsHigh));

        // Case: High surrogate matches, but next char in cs doesn't match next char in searchChars
        char[] searchMismatchLow = {'\uD83D', '\uD83E'}; 
        assertTrue(StringUtils.containsNone(emoji, searchMismatchLow));

        // Case: High surrogate matches, and next char matches
        char[] searchMatchLow = {'\uD83D', '\uDE00'};
        assertFalse(StringUtils.containsNone(emoji, searchMatchLow));
    }


}

